WAIT FOR LSN '0/1B2C3D40' TIMEOUT '2s' MODE standby_replay;

До 19-й версии postgres

-- На primary после commit
SELECT pg_current_wal_insert_lsn() AS write_lsn;

SELECT pg_last_wal_replay_lsn() AS replay_lsn;

if replay_lsn >= write_lsn:
    читать с replica
else:
    подождать и повторить проверку
    или прочитать с primary
